OwnPtr<TemporaryBuffer> buffer = adoptPtr(new TemporaryBuffer());
// Automatically cleaned up when out of scope
```

#### Weak Pointers (`WeakPtr`)
```cpp
// Breaking circular references
class Parent {
    RefPtr<Child> child_;
};

class Child {
