    AddPreferenceRow(layout, kColumnSetId,
                    u"Search Engine:", CreateSearchEngineCombo());
    AddPreferenceRow(layout, kColumnSetId,
                    u"Default Browser:", CreateDefaultBrowserCheckbox());
