  bool AddToIncomingQueue(const tracked_objects::Location& from_here,
                         const Closure& task,
                         TimeDelta delay,
                         bool nestable);

  // Transfer tasks from incoming queue to work queue (MessageLoop thread only)
  void ReloadWorkQueue(TaskQueue* work_queue);

